try { new Function('X', 'applyMacros', "/* 👉 跟手返回：谷雨本来就能「从左边缘往右滑返回」，但松手才跳。这个插件让页面跟着手指走（像 iPhone）：拖到一半能看到底下那一层，松手过半就滑走返回，不够就弹回去；还能开「右边缘往左滑也返回」（单手用），切页的时候淡入，不闪白。纯手势，没有自主行动 */\nif (window.__gyxSwipe) return; window.__gyxSwipe = 1;\nX.feat('gyxSwipe', { n: '👉 跟手返回', desc: '从边缘滑动返回时页面跟着手指走；切页淡入不闪白', auto: false });\nconst K = 'gyxSwipeCfg';\nlet C = { edge: 26, need: 33, right: false, fade: true, shade: true };\ntry { Object.assign(C, JSON.parse(localStorage.getItem(K) || '{}')); } catch (e) {}\nconst save = () => { try { localStorage.setItem(K, JSON.stringify(C)); } catch (e) {} };\nconst vis = el => { if (!el) return false; const cs = getComputedStyle(el); if (cs.display === 'none' || cs.visibility === 'hidden') return false; const r = el.getBoundingClientRect(); return r.width > 40 && r.height > 40; };\n// 松手以后会被关掉 / 退掉的那一层\nfunction target() {\n    const sh = document.getElementById('gyPmSheet'); if (sh && sh.classList.contains('on') && document.body.classList.contains('gyphm') && vis(sh.firstElementChild || sh)) return sh.firstElementChild || sh;\n    const z = el => parseInt(getComputedStyle(el).zIndex, 10) || 0;\n    const ov = [...document.querySelectorAll('.gyx-ov, .modal-overlay, [data-gy-overlay], .gy-aspage, #gyHubOv')].filter(vis).sort((a, b) => z(b) - z(a))[0];\n    if (ov) return ov.querySelector('.gyx-box, .modal-content, .gyhb-box, .gyg-box') || ov;\n    if (document.body.classList.contains('gyphm')) { const a = document.querySelector('#gyPm .pm-app.on, #gyPm .pm-app:last-child'); if (a && vis(a)) return a; }\n    return [...document.querySelectorAll('[id^=\"view-\"]')].find(vis) || null;\n}\nlet G = null;\nwindow.addEventListener('touchstart', e => {\n    G = null; if (!X.on('gyxSwipe') || e.touches.length !== 1) return; const t = e.touches[0], W = innerWidth;\n    const side = t.clientX <= C.edge ? 1 : (C.right && t.clientX >= W - C.edge ? -1 : 0); if (!side) return;\n    G = { x: t.clientX, y: t.clientY, t: Date.now(), side, el: null, on: false };\n}, { capture: true, passive: true });\nwindow.addEventListener('touchmove', e => {\n    if (!G) return; const t = e.touches[0], dx = (t.clientX - G.x) * G.side, dy = Math.abs(t.clientY - G.y);\n    if (!G.on) { if (dy > 30 && dy > dx) { G = null; return; } if (dx < 10) return; G.el = target(); if (!G.el) { G = null; return; } G.on = true; G.el.classList.add('gyx-sw-drag'); }\n    e.stopPropagation();   // 不让谷雨自带的那套「松手才跳」同时动\n    const x = Math.max(0, dx) * G.side; G.el.style.transform = `translateX(${x}px)`; G.dx = Math.max(0, dx);\n    if (C.shade) G.el.style.boxShadow = `${-G.side * 8}px 0 30px rgba(0,0,0,${.25 * (1 - Math.min(1, G.dx / innerWidth))})`;\n}, { capture: true, passive: true });\nfunction end(e, cancel) {\n    if (!G) return; const g = G; G = null; if (!g.on) return; if (e) e.stopPropagation();\n    const el = g.el, w = innerWidth, ok = !cancel && (g.dx > w * C.need / 100 || (g.dx > 60 && Date.now() - g.t < 260));\n    el.classList.remove('gyx-sw-drag'); el.classList.add('gyx-sw-anim');\n    el.style.transform = ok ? `translateX(${w * g.side}px)` : 'translateX(0)';\n    setTimeout(() => {\n        el.classList.remove('gyx-sw-anim'); el.style.transform = ''; el.style.boxShadow = '';\n        if (ok) { try { if (typeof window.gyBack === 'function') window.gyBack('swipe'); } catch (err) {} }\n    }, 220);\n}\nwindow.addEventListener('touchend', e => end(e), { capture: true, passive: true });\nwindow.addEventListener('touchcancel', e => end(e, true), { capture: true, passive: true });\n// 切页淡入\nfunction hookView() {\n    const f = window.switchMainView; if (typeof f !== 'function' || f.__gyxSw) return;\n    const w = function () { const r = f.apply(this, arguments); try { if (X.on('gyxSwipe') && C.fade) { const v = [...document.querySelectorAll('[id^=\"view-\"]')].find(vis); if (v) { v.classList.remove('gyx-pg-in'); void v.offsetWidth; v.classList.add('gyx-pg-in'); setTimeout(() => v.classList.remove('gyx-pg-in'), 320); } } } catch (e) {} return r; };\n    Object.keys(f).forEach(k => { try { w[k] = f[k]; } catch (e) {} }); w.__gyxSw = true; window.switchMainView = w; try { (0, eval)('switchMainView = window.switchMainView'); } catch (e) {}\n}\nwindow.gyxSwipeSet = (k, v) => { C[k] = v; save(); window.gyxSwipeOpen(); };\nwindow.gyxSwipeOpen = function () {\n    X.panel('gyxSwpOv', '👉 跟手返回', `<div class=\"gyx-tip\">从屏幕左边缘往右拖：页面跟着手指走，拖过一段距离松手就返回，不够就弹回去。快速一划也算。</div>\n        <div class=\"gyx-row\">边缘多宽算数 <input type=\"range\" min=\"12\" max=\"60\" value=\"${C.edge}\" onchange=\"gyxSwipeSet('edge',+this.value)\"> ${C.edge}px</div>\n        <div class=\"gyx-row\">拖过屏幕的 <input type=\"range\" min=\"15\" max=\"60\" value=\"${C.need}\" onchange=\"gyxSwipeSet('need',+this.value)\"> ${C.need}% 松手才返回</div>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${C.right ? 'checked' : ''} onchange=\"gyxSwipeSet('right',this.checked)\"> 右边缘往左滑也返回（单手用）</label>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${C.shade ? 'checked' : ''} onchange=\"gyxSwipeSet('shade',this.checked)\"> 拖的时候边上有影子</label>\n        <label class=\"gyx-row\"><input type=\"checkbox\" ${C.fade ? 'checked' : ''} onchange=\"gyxSwipeSet('fade',this.checked)\"> 切页的时候淡入（不闪白）</label>\n        <div class=\"gyx-tip\">这是纯手势，所以没有「TA 会自己做」、今天、小组件和记忆。</div>`);\n};\nwindow.gyxSwipeCfg = () => C;\nwindow.gyxSwipeTarget = target;\nwindow.gyxSwipeState = () => G;\nX.css('gyxSwpCss', `.gyx-sw-drag{transition:none!important;will-change:transform}.gyx-sw-anim{transition:transform .22s cubic-bezier(.2,.8,.2,1)!important}\n.gyx-pg-in{animation:gyxPgIn .28s ease-out}@keyframes gyxPgIn{from{opacity:.35;transform:translateX(14px)}to{opacity:1;transform:none}}`);\nX.mini({ id: 'gyxSwipe', icon: '👉', title: '跟手返回', desc: '滑动返回时页面跟着手指走；切页淡入', cat: '生活', onOpen: () => window.gyxSwipeOpen() });\nhookView(); setInterval(hookView, 3000);\n\n//# sourceURL=gyx-plugin/跟手返回.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 👉 跟手返回 出错：', e); }
/* ==== 🛍️ 装扮商店 ==== */
try { new Function('X', 'applyMacros', "/* 🛍️ 装扮商店：用钱包里的钱买装扮——头像框（樱花、星光、猫耳、彩虹、金边……）、聊天背景、气泡套装（买了直接进「气泡工坊」）。你的、TA 的头像框分开戴，也有一对一对的情侣框。钱包没开就免费拿。TA 也会偷偷买一件送你 */\nif (window.__gyxShop) return; window.__gyxShop = 1;\nX.feat('gyxShop', { n: '🛍️ 装扮商店', desc: '用钱包里的钱买头像框、聊天背景、气泡套装；TA 也会买来送你' });\nconst S = X.store('shop');\nconst ITEMS = [\n    { id: 'f_sakura', k: 'frame', n: '樱花框', p: 18, ico: '🌸', css: 'box-shadow:0 0 0 3px #ffb7c9,0 0 0 5px #fff,0 0 10px #ffb7c9', badge: '🌸' },\n    { id: 'f_star', k: 'frame', n: '星光框', p: 24, ico: '✨', css: 'box-shadow:0 0 0 3px #ffd84d,0 0 14px #ffd84d', badge: '✨' },\n    { id: 'f_cat', k: 'frame', n: '猫耳框', p: 30, ico: '🐱', css: 'box-shadow:0 0 0 3px #3a3a3a', badge: '🐱' },\n    { id: 'f_rainbow', k: 'frame', n: '彩虹框', p: 36, ico: '🌈', css: 'box-shadow:0 0 0 2px #ff6b6b,0 0 0 4px #ffd93d,0 0 0 6px #6bcB77,0 0 0 8px #4d96ff', badge: '' },\n    { id: 'f_gold', k: 'frame', n: '金边框', p: 66, ico: '👑', css: 'box-shadow:0 0 0 3px #d4af37,0 0 0 5px #fff6d5,0 0 0 6px #d4af37', badge: '👑' },\n    { id: 'f_pair_moon', k: 'frame', n: '情侣框 · 日月', p: 52, ico: '🌗', pair: ['☀️', '🌙'], css: 'box-shadow:0 0 0 3px #f6c453,0 0 12px rgba(246,196,83,.7)', css2: 'box-shadow:0 0 0 3px #7d8cff,0 0 12px rgba(125,140,255,.7)' },\n    { id: 'f_pair_heart', k: 'frame', n: '情侣框 · 半颗心', p: 52, ico: '💞', pair: ['💗', '💗'], css: 'box-shadow:0 0 0 3px #ff7aa8', css2: 'box-shadow:0 0 0 3px #ff7aa8' },\n    { id: 'b_peach', k: 'bg', n: '蜜桃渐变', p: 12, ico: '🍑', css: 'background:linear-gradient(160deg,#fff1eb,#ffd6e0)!important' },\n    { id: 'b_mint', k: 'bg', n: '薄荷格子', p: 12, ico: '🌿', css: 'background:#f2fbf6 repeating-linear-gradient(0deg,transparent 0 23px,rgba(80,170,120,.12) 23px 24px),repeating-linear-gradient(90deg,transparent 0 23px,rgba(80,170,120,.12) 23px 24px)!important' },\n    { id: 'b_night', k: 'bg', n: '夜空', p: 20, ico: '🌌', css: 'background:radial-gradient(#fff 1px,transparent 1.5px) 0 0/38px 38px,linear-gradient(#141a3a,#2b2250)!important' },\n    { id: 'b_dots', k: 'bg', n: '奶油波点', p: 12, ico: '🥛', css: 'background:#fffaf0 radial-gradient(#f3d9b1 2px,transparent 2.5px) 0 0/22px 22px!important' },\n    { id: 'b_sky', k: 'bg', n: '晴天', p: 16, ico: '☁️', css: 'background:linear-gradient(#bfe3ff,#f2f9ff)!important' },\n    { id: 'u_jelly', k: 'bubble', n: '气泡 · 果冻', p: 28, ico: '🍬', cfg: { me: { bg: '#ff8fb1', fg: '#fff', r: 24, sh: 6 }, ta: { bg: '#a0c4ff', fg: '#fff', r: 24, sh: 6 } } },\n    { id: 'u_ink', k: 'bubble', n: '气泡 · 水墨', p: 28, ico: '🖌️', cfg: { me: { bg: '#2f2f2f', fg: '#f5f1e8', r: 6 }, ta: { bg: '#f5f1e8', fg: '#2f2f2f', r: 6, bw: 1, bc: '#2f2f2f' } } },\n    { id: 'u_choco', k: 'bubble', n: '气泡 · 巧克力', p: 28, ico: '🍫', cfg: { me: { bg: '#7b4b2a', fg: '#fff3e6', r: 18 }, ta: { bg: '#fff3e6', fg: '#5a3418', r: 18 } } }\n];\nlet D = { own: [], wear: { me: '', ta: {}, bg: '' }, gifts: [] };   // own: [itemId]；wear.ta[cid] = frameId；gifts: {id,cid,at,item,line}\nconst saveD = () => S.set('d', D);\nconst item = id => ITEMS.find(x => x.id === id);\nconst wallet = () => window.gyWallet && typeof window.gyWallet.spend === 'function' ? window.gyWallet : null;\nasync function pay(who, it) { const w = wallet(); if (!w) return { ok: true, free: true }; const r = await w.spend(who, it.p, '装扮商店：' + it.n, { cat: '装扮' }); return r && r.skipped ? { ok: true, free: true } : r; }\nlet lastCss = null;\nfunction apply() {\n    if (!X.on('gyxShop')) { if (lastCss) { lastCss = ''; const st = document.getElementById('gyxShopLive'); if (st) st.textContent = ''; } return; }\n    let sid = null; try { sid = typeof currentChatSessionId !== 'undefined' ? String(currentChatSessionId) : null; } catch (e) {}\n    const R = 'html body #view-chat', av = side => `${R} .chat-msg-row.${side}>div:not(.chat-bubble-wrapper)`;\n    let css = '';\n    const fm = item(D.wear.me), ft = item(sid && D.wear.ta[sid]);\n    const fr = (it, side, second) => it ? `${av(side)} .avatar{${second && it.css2 ? it.css2 : it.css}!important;position:relative}${av(side)}{position:relative}${(it.pair ? it.pair[second ? 1 : 0] : it.badge) ? `${av(side)}::after{content:\"${it.pair ? it.pair[second ? 1 : 0] : it.badge}\";position:absolute;right:-4px;top:-6px;font-size:14px;pointer-events:none}` : ''}` : '';\n    css += fr(fm, 'me', false) + fr(ft, 'other', !!(ft && ft.pair));\n    const bg = item(D.wear.bg); if (bg) css += `${R} #chatMessagesArea{${bg.css}}`;\n    if (css === lastCss) return; lastCss = css;\n    let st = document.getElementById('gyxShopLive'); if (!st) { st = document.createElement('style'); st.id = 'gyxShopLive'; document.head.appendChild(st); } st.textContent = css;\n}\nfunction toBubble(it) { try { const B = window.gyxBubbleData && window.gyxBubbleData(); if (!B) return false; if (!B.themes.some(t => t.shop === it.id)) B.themes.unshift({ id: 'bw' + Date.now().toString(36), n: it.n.replace('气泡 · ', ''), by: 'me', at: Date.now(), shop: it.id, cfg: JSON.parse(JSON.stringify(it.cfg)) }); X.store('bubble').set('d', B); return true; } catch (e) { return false; } }\nwindow.gyxShopBuy = async id => {\n    const it = item(id); if (!it || D.own.includes(id)) return;\n    const r = await pay('me', it); if (!r || !r.ok) { X.toast('没买成', (r && r.reason) || '钱包里没有能用的卡'); return; }\n    D.own.push(id); if (it.k === 'bubble') toBubble(it); await saveD();\n    X.toast(X.v('买到啦', '🛍️ 到手', '装进衣柜了'), it.ico + ' ' + it.n + (r.free ? '（钱包没开，免费拿）' : ' · ¥' + it.p)); window.gyxShopOpen();\n};\nwindow.gyxShopWear = async (id, who) => {\n    const it = item(id); let sid = null; try { sid = String(currentChatSessionId); } catch (e) {}\n    if (who === 'bg') D.wear.bg = D.wear.bg === id ? '' : id;\n    else if (who === 'me') D.wear.me = D.wear.me === id ? '' : id;\n    else if (who === 'pair') { const c = X.cur(); if (c) { const on = D.wear.me === id; D.wear.me = on ? '' : id; D.wear.ta[String(c.id)] = on ? '' : id; } }\n    else { const c = X.char(who) || X.cur(); if (c) D.wear.ta[String(c.id)] = D.wear.ta[String(c.id)] === id ? '' : id; }\n    if (it && it.k === 'bubble') { try { window.gyxBubbleOpen && window.gyxBubbleOpen(); } catch (e) {} return; }\n    await saveD(); lastCss = null; apply(); window.gyxShopOpen();\n};\nwindow.gyxShopOpen = function (tab) {\n    const T = tab || window.__gyxShopTab || 'frame'; window.__gyxShopTab = T; const c = X.cur(), w = wallet();\n    let bal = ''; try { if (w) bal = '钱包余额 ¥' + (w.total('me') || 0); } catch (e) {}\n    const L = ITEMS.filter(x => x.k === T);\n    X.panel('gyxShopOv', '🛍️ 装扮商店', `<div class=\"gyx-row\">${[['frame', '头像框'], ['bg', '聊天背景'], ['bubble', '气泡套装']].map(([k, n]) => `<span class=\"gyx-chip ${T === k ? 'on' : ''}\" onclick=\"gyxShopOpen('${k}')\">${n}</span>`).join('')}<span class=\"gyx-tip\" style=\"margin-left:auto\">${bal || '钱包没开：免费拿'}</span></div>\n        <div class=\"sh-grid\">${L.map(it => { const own = D.own.includes(it.id), wm = D.wear.me === it.id, wt = c && D.wear.ta[String(c.id)] === it.id, wb = D.wear.bg === it.id; return `<div class=\"sh-it${own ? ' own' : ''}\"><div class=\"sh-pv ${it.k}\" style=\"${it.k === 'frame' ? '' : it.k === 'bg' ? it.css.replace(/!important/g, '') : `background:${it.cfg.me.bg}`}\">${it.k === 'frame' ? `<i style=\"${it.css}\">${it.pair ? it.pair[0] : it.badge || ''}</i>` : it.k === 'bubble' ? `<i style=\"background:${it.cfg.ta.bg};color:${it.cfg.ta.fg};border-radius:${it.cfg.ta.r}px\">在吗</i>` : ''}</div><b>${it.ico} ${X.esc(it.n)}</b>\n            ${own ? (it.k === 'frame' ? (it.pair ? `<span class=\"gyx-chip ${wm && wt ? 'on' : ''}\" onclick=\"gyxShopWear('${it.id}','pair')\">${wm && wt ? '摘下' : '一起戴'}</span>` : `<span class=\"gyx-chip ${wm ? 'on' : ''}\" onclick=\"gyxShopWear('${it.id}','me')\">${wm ? '摘下' : '我戴'}</span>${c ? `<span class=\"gyx-chip ${wt ? 'on' : ''}\" onclick=\"gyxShopWear('${it.id}','${c.id}')\">${wt ? '摘下' : '给 ' + X.esc(X.name(c))}</span>` : ''}`) : it.k === 'bg' ? `<span class=\"gyx-chip ${wb ? 'on' : ''}\" onclick=\"gyxShopWear('${it.id}','bg')\">${wb ? '换回去' :